package io.github.diodeme.ji.session.model;

import static io.github.diodeme.ji.session.model.CanonicalSessionState.LifecycleStatus.ACTIVE;
import static io.github.diodeme.ji.session.model.CanonicalSessionState.LifecycleStatus.PAUSED;

import java.util.ArrayList;
import java.util.List;

/** Pure recovery transition: pause unfinished work and resume with a new attempt. */
public final class Recovery {
    private Recovery() {}

    public static CanonicalSessionState pauseAfterRestart(CanonicalSessionState state) {
        if (state.activeRun().isEmpty() || state.status() == PAUSED) {
            return state;
        }
        CanonicalSessionState.Run run = state.activeRun().orElseThrow();
        List<CanonicalSessionState.Turn> pausedTurns = run.turns().stream()
                .map(Recovery::pause)
                .toList();
        CanonicalSessionState.Run paused = new CanonicalSessionState.Run(
                run.id(), PAUSED, java.util.Optional.empty(), pausedTurns,
                run.startedAt(), java.util.Optional.empty());
        return new CanonicalSessionState(
                state.sessionId(), PAUSED, state.revision() + 1, java.util.Optional.of(paused), state.completedRuns());
    }

    public static CanonicalSessionState resume(
            CanonicalSessionState state,
            CanonicalSessionState.AttemptId attemptId,
            String resultEntryId) {
        CanonicalSessionState.Run run = state.activeRun().orElseThrow(
                () -> new IllegalStateException("no paused run to resume"));
        if (state.status() != PAUSED || run.status() != PAUSED || run.turns().isEmpty()) {
            throw new IllegalStateException("only a paused session and run with a turn can resume");
        }
        var turns = new ArrayList<>(run.turns());
        var lastTurn = turns.getLast();
        var attempts = new ArrayList<>(lastTurn.attempts());
        var previous = attempts.getLast();
        attempts.add(new CanonicalSessionState.Attempt(
                attemptId,
                previous.number() + 1,
                previous.step(),
                ACTIVE,
                java.util.Optional.empty(),
                resultEntryId));
        turns.set(turns.size() - 1, new CanonicalSessionState.Turn(
                lastTurn.id(), ACTIVE, java.util.Optional.empty(), attempts,
                lastTurn.tools(), lastTurn.permissions(), lastTurn.compactions()));
        CanonicalSessionState.Run resumed = new CanonicalSessionState.Run(
                run.id(), ACTIVE, java.util.Optional.empty(), turns, run.startedAt(), java.util.Optional.empty());
        return new CanonicalSessionState(
                state.sessionId(), ACTIVE, state.revision() + 1, java.util.Optional.of(resumed), state.completedRuns());
    }

    private static CanonicalSessionState.Turn pause(CanonicalSessionState.Turn turn) {
        if (turn.status() == CanonicalSessionState.LifecycleStatus.TERMINAL) {
            return turn;
        }
        return new CanonicalSessionState.Turn(
                turn.id(),
                PAUSED,
                java.util.Optional.empty(),
                turn.attempts().stream().map(Recovery::pause).toList(),
                turn.tools().stream().map(Recovery::pause).toList(),
                turn.permissions().stream().map(Recovery::pause).toList(),
                turn.compactions().stream().map(Recovery::pause).toList());
    }

    private static CanonicalSessionState.Attempt pause(CanonicalSessionState.Attempt attempt) {
        if (attempt.status() == CanonicalSessionState.LifecycleStatus.TERMINAL) {
            return attempt;
        }
        return new CanonicalSessionState.Attempt(
                attempt.id(), attempt.number(), attempt.step(), PAUSED,
                java.util.Optional.empty(), attempt.resultEntryId());
    }

    private static CanonicalSessionState.ToolExecution pause(CanonicalSessionState.ToolExecution tool) {
        if (tool.status() == CanonicalSessionState.LifecycleStatus.TERMINAL) {
            return tool;
        }
        return new CanonicalSessionState.ToolExecution(
                tool.id(), tool.toolCallId(), tool.toolName(), tool.retryContract(),
                PAUSED, java.util.Optional.empty());
    }

    private static CanonicalSessionState.Permission pause(CanonicalSessionState.Permission permission) {
        if (permission.status() == CanonicalSessionState.LifecycleStatus.TERMINAL) {
            return permission;
        }
        return new CanonicalSessionState.Permission(
                permission.id(), permission.toolExecutionId(), PAUSED,
                java.util.Optional.empty(), permission.expiresAt());
    }

    private static CanonicalSessionState.Compaction pause(CanonicalSessionState.Compaction compaction) {
        if (compaction.status() == CanonicalSessionState.LifecycleStatus.TERMINAL) {
            return compaction;
        }
        return new CanonicalSessionState.Compaction(
                compaction.id(), PAUSED, java.util.Optional.empty(), compaction.resultEntryId());
    }
}

