private static List<CanonicalSessionState.Compaction> pauseCompactions(List<CanonicalSessionState.Compaction> compactions) {
    return compactions.stream().map(compaction -> {
        if (compaction.status() != CanonicalSessionState.CompactionStatus.RUNNING) return compaction;
        var attempts = new ArrayList<>(compaction.attempts());
        CanonicalSessionState.Attempt current = attempts.getLast();
        attempts.set(attempts.size() - 1, current.pause(current.revision()));
        return new CanonicalSessionState.Compaction(
                compaction.id(), compaction.sessionId(), CanonicalSessionState.CompactionStatus.PAUSED,
                Optional.empty(), increment(compaction.revision()), attempts, Optional.empty());
    }).toList();
}
